@startuml

class Bus {
  + number : int
}

class Trajectory {
  + destination : string
}

class Line {
  + number : int
  + category : string
}

class MensoTicket {
  + validity_period : string
}

class Trip {
  + time : time
  + date : date
}

class Invoice {
  + total_amount : double
  + discount : double
}

class Customer {
  + home_address : string
  + office_address : string
  + working_hours : string
}

class MensoCard {
  + card_number : string
}

class OtherCard {
  + card_number : string
}

Bus "0..*" -- "0..*" Trajectory : is used for
Line "1" -- "1..*" Trajectory : groups
Bus "0..*" -- "0..*" Trajectory : is assigned to
MensoTicket "1" -- "1" Customer : is subscribed by
Customer "1" -- "0..*" Invoice : receives
MensoCard "1" -- "0..*" Trip : is used for
OtherCard "1" -- "0..*" Trip : is used for
Trip "0..*" -- "1" Line : is for
Trip "0..*" -- "1" Invoice : is collected for

@enduml

